import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  count = 0;

  get isZero(): boolean {
    return this.count === 0;
  }

  inc(): void {
    this.count++;
  }

  dec(): void {
    if (!this.isZero) {
      this.count--;
    }
  }

  reset(): void {
    this.count = 0;
  }
}

